<?php require 'config/db.php';$blogs=$pdo->query("SELECT * FROM blogs WHERE status='published' ORDER BY published_at DESC,id DESC")->fetchAll();$page_title='Blog';include 'includes/header.php';?><section class="page-hero"><div class="container"><span class="eyebrow">Blogs</span><h1>Ideas for <span class="gradient-text">better stock control</span>.</h1></div></section><section class="content-shell"><div class="container card-grid"><?php foreach($blogs as $b):?><article class="glass-card image-card blog-card"><img src="<?=e($b['image_url'])?>" alt="<?=e($b['title'])?>"><div class="body"><span class="eyebrow"><?=date('d M Y',strtotime($b['published_at']))?></span><h3><?=e($b['title'])?></h3><p><?=e($b['excerpt'])?></p><a class="btn btn-ghost" href="blog?slug=<?=urlencode($b['slug'])?>"><i class="fa-solid fa-arrow-right"></i> Read Article</a></div></article><?php endforeach;?></div></section><?php include 'includes/footer.php'; ?>